659:   function simulateTick() {
660:     if (!state) return;
661:     state.tick++;
662:     const scale = periodScale();
663:     state.elapsedDays = (state.elapsedDays || 0) + PERIOD_DAYS[state.period];
664:     state.hour = (state.hour + .24 * scale) % 24;
665:     state.moodBoost *= Math.pow(.966, scale);
666:     if (Math.abs(state.moodBoost) < .05) state.moodBoost = 0;
667:     recalc();
668:     const hasPower = state.powerCap >= state.powerUse;
669:     const hasWater = state.waterCap >= state.waterUse;
670:     let changed = false;
671:     for (const b of state.buildings.slice()) {
672:       const d = defOf(b);
673:       if (!d || !d.kind || !d.kind.startsWith('zone')) continue;
674:       const ok = hasPower && hasWater && roadAccess(b);
675:       if (b.level === 0) {
676:         const kind = zoneArtKind(d);
677:         if (ok && demandFor(kind) > 0 && state.happiness >= 38) {
678:           b.growth += (1 + (state.happiness > 66 ? .5 : 0)) * scale;
679:           if (b.growth >= 2) { b.level = 1; b.growth = 0; b.evo = 0; changed = true; }
680:         } else b.growth = Math.max(0, b.growth - .5 * scale);
681:       } else {
682:         const school = nearbyArt(b, ['school']);
683:         const hospital = nearbyArt(b, ['hospital']);
684:         let maxLv = 3;
685:         if (kindOf(d) === 'r') maxLv = 2 + (school ? 1 : 0) + (hospital ? 1 : 0);
686:         if (b.level < Math.min(d.maxLevel || 3, maxLv) && ok && state.happiness >= 50) {
687:           b.evo += (state.happiness >= 68 ? 2 : 1) * scale;
688:           const need = [0, 7, 13, 21][b.level] || 99;
689:           if (b.evo >= need) { b.level++; b.evo = 0; changed = true; }
690:         } else if (b.evo > 0) b.evo = Math.max(0, b.evo - scale);
691:       }
692:     }
693:     if (changed) recalc();
694:     state.money += (state.income - state.expense) * scale;
695:     // resource warnings
696:     if (!state.warned.power && state.powerUse > state.powerCap && state.powerUse > 0) {
697:       toast('Listrik tidak cukup! Bangun pembangkit atau taman surya.', 'bad', 'bolt');
698:       state.warned.power = true;
699:     }
700:     if (state.powerUse <= state.powerCap) state.warned.power = false;
701:     if (!state.warned.water && state.waterUse > state.waterCap && state.waterUse > 0) {
702:       toast('Pasokan air kurang! Bangun menara air tambahan.', 'bad', 'drop');
703:       state.warned.water = true;
704:     }
705:     if (state.waterUse <= state.waterCap) state.warned.water = false;
706:     checkUnlocks();
707:     checkMissions();
708:     // random city event
709:     state.eventTimer = (state.eventTimer || 48) - scale;
710:     if (state.eventTimer <= 0) {
711:       state.eventTimer = 55 + Math.floor(Math.random() * 25);
712:       if (!state.modalPause && state.population >= 20) setTimeout(showRandomEvent, 350);
713:     }
714:     if (state.tick % Math.max(1, Math.round(2 / scale)) === 0) spawnCars();
715:     if (state.tick % Math.max(1, Math.round(20 / scale)) === 0) saveGame(true);
716:     updateAll();
717:     updateSelection();
718:   }
719:   function kindOf(def) { return def.kind === 'zone-r' ? 'r' : def.kind === 'zone-c' ? 'c' : 'i'; }
