721:   function checkUnlocks(silent) {
722:     if (!state) return;
723:     for (const id in DEFS) {
724:       const d = DEFS[id];
725:       if (!d.unlockPop || d.unlockPop > state.maxPop) continue;
726:       if (!state.unlocked[id]) {
727:         state.unlocked[id] = true;
728:         if (!silent) {
729:           toast(`Bangunan baru terbuka: ${d.name}`, 'reward', 'trophy');
730:           sfx.unlock();
731:         }
732:       }
733:     }
734:   }
735:   function checkMissions() {
736:     if (!state) return;
737:     for (const m of KK.MISSIONS) {
738:       if (state.missionsDone[m.id]) continue;
739:       if (m.check(state)) {
740:         state.missionsDone[m.id] = true;
741:         state.money += m.reward;
742:         sfx.reward();
743:         toast(`Misi selesai: ${m.label} · +${money(m.reward)}`, 'reward', 'trophy');
744:         if (m.id === 'metro' && !state.won) {
745:           state.won = true;
746:           setTimeout(showWin, 900);
747:         }
748:         updateHUD(true); renderMissions();
749:       }
750:     }
751:   }
