215:       const foam = (dir) => {
216:         const n = neighbor(world, x, y, dir);
217:         if (!n || n.terrain === 'water') return;
218:         if (dir === 'n') line(ctx, T, R, 'rgba(240,255,255,.6)', 2.2);
219:         if (dir === 'e') line(ctx, R, B, 'rgba(240,255,255,.55)', 2);
220:         if (dir === 's') line(ctx, B, L, 'rgba(240,255,255,.55)', 1.8);
221:         if (dir === 'w') line(ctx, L, T, 'rgba(240,255,255,.6)', 2);
222:       };
223:       foam('n'); foam('e'); foam('s'); foam('w');
224:       return;
225:     }
226:     let base;
227:     if (tile.terrain === 'sand') base = SAND[Math.floor(h * SAND.length)];
228:     else base = GRASS[Math.floor(h * GRASS.length)];
229:     poly(ctx, [T, R, B, L], base);
230:     if (tile.terrain === 'grass') {
231:       ctx.strokeStyle = 'rgba(45,100,40,.055)'; ctx.lineWidth = .8;
232:       ctx.stroke();
233:       if (h > .32) {
