235:         const gy = T.y + 9 + hash(x, y + 5) * 12;
236:         ctx.globalAlpha = .35;
237:         line(ctx, { x: gx, y: gy }, { x: gx + 1.5, y: gy - 3.4 }, '#4d8a3e', 1);
238:         line(ctx, { x: gx + 1, y: gy }, { x: gx + 4, y: gy - 2.8 }, '#4d8a3e', .9);
239:         line(ctx, { x: gx + 1, y: gy }, { x: gx - 1.7, y: gy - 2.6 }, '#5a9648', .9);
240:         if (h > .75) {
241:           ctx.fillStyle = h > .9 ? '#f7d85e' : '#f2fdf8';
242:           ctx.beginPath(); ctx.arc(gx + 6, gy - 3, 1.15, 0, 7); ctx.fill();
243:         }
244:         ctx.globalAlpha = 1;
245:       }
246:     } else if (tile.terrain === 'sand') {
247:       ctx.globalAlpha = .28;
248:       ctx.fillStyle = '#b99f66';
249:       for (let i = 0; i < 2; i++) {
250:         const sx = T.x + 12 + hash(x + i, y + 1) * 30;
251:         const sy = T.y + 8 + hash(x + 2, y + i) * 12;
252:         ctx.beginPath(); ctx.arc(sx, sy, .9, 0, 7); ctx.fill();
253:       }
254:       ctx.globalAlpha = 1;
255:     }
256:   }
257:   // Directions match the four visible diamond edges: n=T-R (+x), e=R-B (+y),
258:   // s=B-L (-x), and w=L-T (-y).
259:   function neighbor(world, x, y, dir) {
