261:     const dy = dir === 'e' ? 1 : dir === 'w' ? -1 : 0;
262:     const nx = x + dx, ny = y + dy;
263:     if (nx < 0 || ny < 0 || nx >= world.gridSize || ny >= world.gridSize) return null;
264:     return world.grid[ny * world.gridSize + nx];
