287:     const wall = o.wall || '#f0e3c8';
288:     const left = o.left || shade(wall, .84);
289:     const right = o.right || shade(wall, .67);
290:     const top = o.top || wall;
291:     const up = (p, dy) => ({ x: p.x, y: p.y - (dy || height) });
292:     poly(ctx, [g.L, g.B, up(g.B), up(g.L)], left);
293:     poly(ctx, [g.B, g.R, up(g.R), up(g.B)], right);
294:     poly(ctx, [up(g.T), up(g.R), up(g.B), up(g.L)], top);
