303:   function drawPitchedRoof(ctx, g, height, rise, color, opt) {
304:     const o = opt || {};
305:     const y = height;
306:     const T = { x: g.T.x, y: g.T.y - y }, R = { x: g.R.x, y: g.R.y - y }, B = { x: g.B.x, y: g.B.y - y }, L = { x: g.L.x, y: g.L.y - y };
307:     const cx = (T.x + B.x) / 2, cy = (T.y + B.y) / 2;
