309:     const over = o.over || 0;
310:     if (over) {
311:       const dirs = [[T, R], [R, B], [B, L], [L, T]];
312:       for (const [a, b] of dirs) {
313:         const na = { x: a.x + (a.x - cx) * .06, y: a.y + (a.y - cy) * .06 };
314:         const nb = { x: b.x + (b.x - cx) * .06, y: b.y + (b.y - cy) * .06 };
