474:     ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
475:     drawBackground(ctx, viewW, viewH, time);
476:     ctx.setTransform(dpr * zoom, 0, 0, dpr * zoom, dpr * (viewW / 2 - cam.x * zoom), dpr * (viewH / 2 - cam.y * zoom));
477:     drawPlate(ctx, world.gridSize);
478:     const left = cam.x - viewW / (2 * zoom) - 90;
479:     const right = cam.x + viewW / (2 * zoom) + 90;
480:     const top = cam.y - viewH / (2 * zoom) - 200;
481:     const bottom = cam.y + viewH / (2 * zoom) + 130;
482:     for (let y = 0; y < world.gridSize; y++) {
483:       for (let x = 0; x < world.gridSize; x++) {
484:         const t = world.grid[y * world.gridSize + x];
485:         if (!t) continue;
486:         const s = iso(x, y);
487:         if (s.x < left - 90 || s.x > right + 90 || s.y < top - 80 || s.y > bottom + 80) continue;
488:         drawTerrain(ctx, world, x, y, t, time);
489:         if (t.road) drawRoad(ctx, world, x, y, t);
490:       }
491:     }
492:     if (opts.placements && opts.placements.length) {
493:       drawPlacementCandidates(ctx, opts.placements, { left, right, top, bottom }, time);
494:     }
495:     const objs = [];
496:     for (const b of world.buildings) {
497:       const s = iso(b.x, b.y);
498:       if (s.x < left - 260 || s.x > right + 260 || s.y < top - 120 || s.y > bottom + 260) continue;
499:       objs.push({ d: b.x + b.y + (b.w + b.h - 2) * .34, b });
500:     }
501:     if (world.cars) {
502:       for (const c of world.cars) {
503:         if (c.x < left / 32 - 20 || c.y < top / 16 - 20) { /* rough */ }
504:         objs.push({ d: c.x + c.y, car: c });
505:       }
506:     }
507:     objs.sort((a, b) => a.d - b.d);
508:     for (const o of objs) {
509:       if (o.b) drawObject(ctx, o.b, time);
510:       else drawCar(ctx, o.car, time);
511:     }
512:     if (opts.selected) {
513:       const b = opts.selected;
514:       const pts = diamondPoints(b.x, b.y, b.w, b.h, .02);
515:       ctx.save();
516:       ctx.setLineDash([6, 4]);
517:       poly(ctx, pts, 'rgba(255,255,255,.05)', 'rgba(255,255,255,.9)', 2.2);
518:       ctx.setLineDash([]);
519:       ctx.restore();
520:       if (DEFS[b.defId] && DEFS[b.defId].radius) drawZoneRadius(ctx, b, 'rgba(46,194,126,.55)');
521:     }
522:     if (opts.ghost) drawGhost(ctx, opts.ghost, time);
523:     // night overlay (screen space)
524:     if (NIGHT > .02) {
525:       ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
526:       ctx.fillStyle = `rgba(14,26,62,${NIGHT * .3})`;
527:       ctx.fillRect(0, 0, viewW, viewH);
528:       if (opts.dusk) {
529:         ctx.fillStyle = `rgba(255,127,58,${opts.dusk * .12})`;
530:         ctx.fillRect(0, 0, viewW, viewH);
531:       }
532:     }
