608:       poly(ctx, [{ x: -14, y: -3.4 }, { x: -10, y: -3.7 }, { x: -8.5, y: -2.2 }, { x: -8.5, y: 2.8 }, { x: -14, y: 2.8 }], '#a9d8df');
